INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('ea6052d3-ad31-47de-bae2-56b9f706a103', '21feff02-016d-46e2-bb9d-c27495133b1b', '51. óra: A kör', 'A kör elemei: középpont (O), sugár (r), átmérő (d), húr, körív, körző használata.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "6a82244d-34ec-4765-b1e7-a61be80bb7fd", "text": "Hogyan viszonylik a kör átmérője (d) a sugárhoz (r)?", "type": "multiple-choice", "options": [{"id": "39753036-4e63-4692-9d8f-192c244ba075", "text": "d = 2 * r (az átmérő a sugár kétszerese)", "isCorrect": true}, {"id": "b99bb96c-e6ef-4b61-9be1-206472358c2b", "text": "d = r / 2", "isCorrect": false}, {"id": "145f0343-6fca-42e0-b78e-147f67833e9c", "text": "d = r + 5", "isCorrect": false}, {"id": "40ba0502-2f6c-44a3-922d-a4b3bbdaa7ac", "text": "d = r * r", "isCorrect": false}], "timeLimit": 15}, {"id": "2d3952fb-c87b-41b6-a1a8-b2539047d0b0", "text": "Ha a kör sugara r = 5 cm, mennyi az átmérője (d)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "03c4a714-1f9c-4b4b-ae6c-c1122f34326c", "text": "Ha a kör átmérője d = 16 cm, mennyi a sugara (r)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "71790c80-ed59-4e51-a0bd-e3e7c86f2edf", "text": "A körvonal pontjai a középponttól egyenlő távolságra (sugárnyira) vannak.", "type": "true-false", "options": [{"id": "45dfb588-3e5c-4c3e-b2ea-3b2077759a39", "text": "Igaz", "isCorrect": true}, {"id": "d64c71a2-fbd9-43cc-b18a-042111e5bc0d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e3252b32-3530-4acc-898a-3b41b701b2f3", "text": "Mi a kör leghosszabb húrja?", "type": "multiple-choice", "options": [{"id": "5b76fc8b-1932-4c99-b2a2-f1caca6aa8fd", "text": "Az átmérő", "isCorrect": true}, {"id": "5a7a1248-f09d-44d9-ab30-789267f122df", "text": "A sugár", "isCorrect": false}, {"id": "5e454fc9-4314-46b9-a4ae-a50b99f79243", "text": "A körív", "isCorrect": false}, {"id": "eedc712c-4edc-4d06-a507-d8afef199b63", "text": "A körcikk", "isCorrect": false}], "timeLimit": 15}, {"id": "96f1ef33-6454-4237-ae45-37675e6be40c", "text": "A körző a körök rajzolására és távolságok másolására szolgáló szerkesztőeszköz.", "type": "true-false", "options": [{"id": "4a09eb8d-8551-4f7e-ba90-dc795ea284e9", "text": "Igaz", "isCorrect": true}, {"id": "ab1a4330-4833-45b6-95d0-e7ef92c16693", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "31bc4d8d-41e7-458a-9901-f239530931d0", "text": "A kör belsejében lévő pontok távolsága a középponttól kisebb, mint a sugár.", "type": "true-false", "options": [{"id": "9b203629-992c-4ca8-ad4e-32236edf90f6", "text": "Igaz", "isCorrect": true}, {"id": "65506755-ded5-4a05-9573-38152d3401ef", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('8941691a-cf06-44ad-9074-82cda9a3ea25', '21feff02-016d-46e2-bb9d-c27495133b1b', '52. óra: A szakasz felezőmerőlegese', 'A szakaszfelező merőleges tulajdonságai, szerkesztése körzővel és vonalzóval.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "e66b81df-b2f8-4201-b8b9-750b8fe1aee7", "text": "Mi a szakaszfelező merőleges egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "45430549-4185-4d79-a703-0d1fbf297570", "text": "A szakasz felezőpontján áthaladó, a szakaszra merőleges egyenes, melynek pontjai egyenlő távolságra vannak a szakasz két végpontjától", "isCorrect": true}, {"id": "11544bd2-68f0-43eb-b5b6-f5b337f6409a", "text": "A szakasszal párhuzamos egyenes", "isCorrect": false}, {"id": "38be72a8-9b66-4c9d-9a06-27f7cd911aa5", "text": "A szakasz egyik végpontján átmenő egyenes", "isCorrect": false}, {"id": "cf6ecafc-7593-45ee-a2a1-86406ee0f151", "text": "Minden szakaszhoz 2 felezőmerőleges tartozik", "isCorrect": false}], "timeLimit": 15}, {"id": "b96f099e-3d42-40da-982b-16c10d25ec04", "text": "Hány felezőmerőlegese van egy szakasznak a síkban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "d3f0fcf0-6821-46ec-8c11-2ed562122e87", "text": "A szakaszfelező merőleges egyenes pontjai egyenlő távolságra vannak a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "4c2bb263-5eaf-4aa2-90a2-c38c616ed84f", "text": "Igaz", "isCorrect": true}, {"id": "21aa9cf2-bdfe-4b95-a64a-1c4c9c527634", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8a0793e4-2414-43a3-a486-7b2f0c94fcd7", "text": "A szakasz felezőmerőlegesének megszerkesztéséhez a szakasz felénél nagyobb körzőnyílás szükséges.", "type": "true-false", "options": [{"id": "72cc07c4-f502-44f4-a8d9-d11639417098", "text": "Igaz", "isCorrect": true}, {"id": "e0b6a5a8-7a5b-432b-9412-5731f09327bc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "18be913f-2b6a-4a45-a105-5e8ff68ca006", "text": "Hány fokos szöget zár be a felezőmerőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "882568c3-88cf-4c77-8af1-7a567fe2ed49", "text": "A háromszög oldalfelező merőlegesei egy pontban metszik egymást (a körülírt kör középpontjában).", "type": "true-false", "options": [{"id": "a963d983-2e5b-4b0c-ba79-bf0d84844e61", "text": "Igaz", "isCorrect": true}, {"id": "22017eb9-2ad6-4d71-85c6-586fcf280e9e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2039debc-bcf9-4a13-8109-9878d3687d2c", "text": "Egy 8 cm-es szakasz felezőpontja a végponttól 4 cm-re van.", "type": "true-false", "options": [{"id": "d3f81e41-d8ca-4924-b1c3-8ffd71743317", "text": "Igaz", "isCorrect": true}, {"id": "b75ffab7-1c58-4136-b86f-eb72b0c6e6f1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('c503b84f-a55d-4291-a1d2-0823d4a166f0', '21feff02-016d-46e2-bb9d-c27495133b1b', '53. óra: Szerkesztések', 'Alapszerkesztések: szakasz másolása, szög másolása, merőleges és párhuzamos állítása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "2b8190b1-1db2-47eb-9ff1-038eb8346072", "text": "Milyen eszközt használunk körök és ívek rajzolásához szerkesztéskor?", "type": "multiple-choice", "options": [{"id": "7769462c-508a-41b1-95ef-a4993014a8b3", "text": "Körzőt", "isCorrect": true}, {"id": "d83f9a75-ea7f-4c1d-91d7-c4bf1ca23be0", "text": "Szögmérőt", "isCorrect": false}, {"id": "1ee4c8a6-6b2e-40eb-9c8a-b014fff867f8", "text": "Radírt", "isCorrect": false}, {"id": "6872a93f-1d6c-4ebc-9383-b4399edc36b5", "text": "Tollat", "isCorrect": false}], "timeLimit": 15}, {"id": "5907606b-66c4-491a-86ec-d657c38d7748", "text": "Milyen vonalzót használunk a tiszta geometrikai szerkesztésekhez?", "type": "multiple-choice", "options": [{"id": "11e24221-3913-4867-ab13-903e588c7d0f", "text": "Beosztás nélküli (egyenes) vonalzót", "isCorrect": true}, {"id": "4c31ae41-b310-4c2d-b528-a82394bad685", "text": "Derékszögű vonalzót beosztással", "isCorrect": false}, {"id": "df8a8059-a735-4922-be21-103cbb36f740", "text": "Görbe vonalzót", "isCorrect": false}, {"id": "1a863ab0-1f35-4fb0-ba71-a9b5ffa18690", "text": "Mérőszalagot", "isCorrect": false}], "timeLimit": 15}, {"id": "47266879-8b90-408e-a278-43b0952d60e6", "text": "Szakasz másolásakor körzővel mérjük fel a szakasz hosszát.", "type": "true-false", "options": [{"id": "e5713bea-4c9a-403c-a388-c638918a1d64", "text": "Igaz", "isCorrect": true}, {"id": "c7cf34c2-aef9-4aee-9f40-f0c88a9b5f78", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dad7c47e-b0b8-4786-91af-3577803edcf5", "text": "A szerkesztéseknél a körzőívek metszéspontjai adják meg a keresett pontokat.", "type": "true-false", "options": [{"id": "aa166913-6891-44ec-a7b2-871490bceea1", "text": "Igaz", "isCorrect": true}, {"id": "f9758edf-ac36-4635-a6fe-a75f5738771b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2bb6527c-42c2-4c8d-aa07-e7bf689a36e3", "text": "Hány fokos szöget zár be két egymásra merőleges egyenes?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "64fe413f-fb4e-4d58-9232-68f55722af2e", "text": "Két párhuzamos egyenes sehol sem metszi egymást a síkban.", "type": "true-false", "options": [{"id": "23498e19-bebb-4d72-981c-329e22a606f6", "text": "Igaz", "isCorrect": true}, {"id": "915cd89b-3dac-4651-8a43-b9daed035cb7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7fee960f-e6a0-4db5-98bb-12e85cbe7adc", "text": "A pontos és esztétikus szerkesztés alapkövetelmény a geometriában.", "type": "true-false", "options": [{"id": "1d0b9ccb-c4b5-4e46-b85d-c32e002ff0c1", "text": "Igaz", "isCorrect": true}, {"id": "83f968ed-520a-4cd3-a961-73f75dff7a3f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('6cf306c3-eb04-4106-83d2-74462ba06e29', '21feff02-016d-46e2-bb9d-c27495133b1b', '54. óra: Szerkesztések II.', 'Egyszerű szerkesztési feladatok: háromszög szerkesztése oldalaiból (SSSZ), háromszög-egyenlőtlenség.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "e5277e10-d0b5-469d-8c8b-64b7469ae6a2", "text": "Mi a háromszög-egyenlőtlenség szabálya?", "type": "multiple-choice", "options": [{"id": "aa82eee1-c901-4a96-807f-624388667585", "text": "A háromszög bármely két oldalának összege nagyobb a harmadik oldalnál (a + b > c)", "isCorrect": true}, {"id": "9ac8a115-099a-4740-9237-de01b17b6331", "text": "A három oldal összege 180", "isCorrect": false}, {"id": "1a82c777-dd20-4819-a338-7dc0a2e643e4", "text": "A két rövidebb oldal összege kisebb a harmadiknál", "isCorrect": false}, {"id": "6a621ad1-3c0a-4621-8128-04468fd0be6e", "text": "Minden oldal egyenlő", "isCorrect": false}], "timeLimit": 15}, {"id": "82847b26-2900-4502-bc63-6b4202b21203", "text": "Szerkeszthető-e háromszög a 3 cm, 4 cm, 8 cm oldalakkal? (3+4 = 7 < 8)", "type": "true-false", "options": [{"id": "abac7059-d245-4f4f-8297-7ef5a7536548", "text": "Igaz", "isCorrect": false}, {"id": "8794b9dc-e41e-43b4-a3d0-10e93550fff5", "text": "Hamis (nem teljesül a háromszög-egyenlőtlenség)", "isCorrect": true}], "timeLimit": 15}, {"id": "874319ce-58f5-4b8d-b6d8-28b3cecc1d29", "text": "Szerkeszthető-e háromszög 5 cm, 6 cm, 7 cm oldalakkal?", "type": "true-false", "options": [{"id": "fe6daba1-aa57-4ae2-bd81-e9736f03133b", "text": "Igaz (5+6 > 7)", "isCorrect": true}, {"id": "be21e4c7-aeb9-4729-9207-921d9c7c1c0b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3e71256a-a68a-44b8-91ad-f9d6951954bb", "text": "Hány adatra van szükség legalább egy háromszög egyértelmű megszerkesztéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "e4747763-76f7-4f91-b756-236cd9353355", "text": "A háromszög szerkesztésének lépései: Vázlat -> Adatok -> Szerkesztés -> Ellenőrzés.", "type": "true-false", "options": [{"id": "a5333004-119e-438b-a71d-c92fe66f7b66", "text": "Igaz", "isCorrect": true}, {"id": "d2f32469-4d14-4cd4-8bf3-4a9ecd741ff5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "88caffe3-f7b0-4ce4-8916-9e501c01a015", "text": "Szerkeszthető-e háromszög 2 cm, 3 cm, 5 cm oldalakkal? (2+3 = 5)", "type": "true-false", "options": [{"id": "10f9695d-1db3-4965-8c6a-d557fafd6d7e", "text": "Igaz", "isCorrect": false}, {"id": "cbd50cb7-a58c-49fe-b552-ef7d0e2bae21", "text": "Hamis (kell hogy > legyen, nem =)", "isCorrect": true}], "timeLimit": 15}, {"id": "9700d687-68ca-40c3-80b5-47168d1f1b83", "text": "Az egyenlő oldalú háromszög minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "ee359d60-dc78-4e9a-943b-a37aafa5cadc", "text": "Igaz", "isCorrect": true}, {"id": "506dc867-a0fc-4f51-965f-88b46f3b1a20", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('204e5a48-df2c-42fd-99e3-5b7d1f1533a2', '21feff02-016d-46e2-bb9d-c27495133b1b', '55. óra: Számonkérés', 'Számonkérés a síkbeli alakzatokból és alapszerkesztésekből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "bcc22d33-b356-4968-b7ec-c5293e349519", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "efcba37f-ab5b-415f-bac4-a11791e01653", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "ac2f9412-5a42-45f0-9a42-e8a9fb8b9bb9", "text": "3. Szerkeszthető-e háromszög 4 cm, 5 cm, 10 cm oldalakkal?", "type": "true-false", "options": [{"id": "ca06ba03-4170-43dd-9885-2034e138f0f6", "text": "Igaz", "isCorrect": false}, {"id": "0b58338d-cf78-4638-9976-189f6bf734fc", "text": "Hamis (4+5 < 10)", "isCorrect": true}], "timeLimit": 15}, {"id": "9e8678d6-181f-419a-aa5e-083662f7b531", "text": "4. Ha a kör sugara 7 cm, mennyi az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "6b88e7aa-25b6-481d-86dc-3ef07a8e1be3", "text": "5. Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "9cb8d74b-92b1-400e-ba2c-95eaa4526faf", "text": "6. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "dd962363-9244-45a8-92a5-ebfc5748c561", "text": "Igaz", "isCorrect": true}, {"id": "9986a06f-a773-4cfa-a97e-cd0fe479f058", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d8419bed-2132-41a0-a5ba-d07843fb64f3", "text": "7. Milyen szög a 120°-os szög?", "type": "multiple-choice", "options": [{"id": "a8b834ef-5943-49ef-8e06-70ab59e634e3", "text": "Tompaszög", "isCorrect": true}, {"id": "50e3bc76-0778-46bd-8765-549c8d3a8450", "text": "Hegyesszög", "isCorrect": false}, {"id": "af38a192-e87c-4dc2-bdae-2e56fd4c3dc9", "text": "Derékszög", "isCorrect": false}, {"id": "fad20271-1e77-431e-86e4-49bca08bf78a", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "66d915c3-af02-4dce-95b9-7e66137a44ae", "text": "8. Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "fcb60a2e-7f44-489e-b96b-82c980b944f9", "text": "9. Az egybevágó alakzatok területe megegyezik.", "type": "true-false", "options": [{"id": "bf0881a1-5af2-4f74-bb01-30d1b089ccb7", "text": "Igaz", "isCorrect": true}, {"id": "d3ec8c74-4b31-40a4-960e-376561c8e1d7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "15017609-d643-4410-ba59-fdd349d9f9b4", "text": "10. Hány fokosak a szabályos háromszög szögei?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW()),
('f4ce02e1-390f-492f-bc1d-ea53bc1537ec', '21feff02-016d-46e2-bb9d-c27495133b1b', '56. óra: Matematikai játékok', 'Geometriai kirakók (Tangram), alakzatok építése, stratégiák.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "f1052b3c-42ce-4009-80ae-9e52e02e78f7", "text": "Hány darabból (tanból) áll a klasszikus Tangram kirakó játék?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "c83102fe-7cfa-4692-abc9-5901812e93df", "text": "Milyen síkidomokból áll a Tangram készlet?", "type": "multiple-choice", "options": [{"id": "c85c8059-4dbc-42ac-adff-893d55f0d3f9", "text": "5 háromszög, 1 négyzet, 1 paralelogramma", "isCorrect": true}, {"id": "a88b7eb5-9eff-4206-8623-854e57b7a395", "text": "7 négyzet", "isCorrect": false}, {"id": "1abb64e7-e1df-480e-a2d1-0c022d3a81fa", "text": "7 kör", "isCorrect": false}, {"id": "0594f632-3856-4660-acb5-71f0da4eda4d", "text": "3 háromszög, 4 téglalap", "isCorrect": false}], "timeLimit": 15}, {"id": "3e7eea71-a03b-4562-b428-d534553e3401", "text": "A Tangram elemeiből sokféle figura (állatok, emberi alakok, tárgyak) kirakható.", "type": "true-false", "options": [{"id": "eabd3ea0-5d09-4650-aa49-e52169b18b68", "text": "Igaz", "isCorrect": true}, {"id": "4963232f-b1a4-465c-adc0-c58a93cd161d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "028e2b80-55f2-46a5-897b-9045404cf897", "text": "A kirakós játékok fejlesztik a térszemléletet és a síkbeli alakzatok felismerését.", "type": "true-false", "options": [{"id": "32f6c82a-9ee4-4666-b07f-8bfda54f90d1", "text": "Igaz", "isCorrect": true}, {"id": "ace62bf5-61a9-4ea9-9512-0d6d946d6cdc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f6b63c28-43e3-4f5e-83f2-99fe42b489ca", "text": "A szabályos sokszögekkel hégmentesen lefedhető a sík (pl. szabályos hatoszögekkel).", "type": "true-false", "options": [{"id": "548a7005-3969-47e6-801d-cf6a802bf079", "text": "Igaz", "isCorrect": true}, {"id": "85b2d968-1372-40fb-8dc3-db5417160415", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "06423b0d-3e53-4efe-a2d1-73b23fd89688", "text": "Hány oldala van a szabályos hexagonnak (hatszögnek)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "77073edf-392e-4754-9619-420dafa1c5e2", "text": "A geometriai játékok során a próbálgatás és a logikai tervezés együtt segít a megoldásban.", "type": "true-false", "options": [{"id": "d5b967b7-6127-4c51-81b6-b573c4fe1564", "text": "Igaz", "isCorrect": true}, {"id": "ca0f2f7f-bc3c-4744-b762-d40afebd539f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('c7a0065b-5600-4359-97ea-c3f192408eb7', '21feff02-016d-46e2-bb9d-c27495133b1b', '57. óra: Tengelyes tükrözés', 'Tengelyes tükrözés fogalma, tengely (t), tárgy és tükörkép (A és A'').', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "a7b97881-5f23-4f1d-b579-b6fcece0456a", "text": "Mi a tengelyes tükrözés lényege egy ''t'' tengelyre nézve?", "type": "multiple-choice", "options": [{"id": "79e05b79-207c-4050-869a-eb21d4b3abe5", "text": "A pont és tükörképe a tengelyre merőleges egyenesen van, és egyenlő távolságra van a tengelytől", "isCorrect": true}, {"id": "b890e492-7cfa-4c85-ba5a-c8f0c115bd85", "text": "A pontot eltoljuk párhuzamosan", "isCorrect": false}, {"id": "8a623f96-e67a-4ba4-866c-afab831dbb90", "text": "A pontot elforgatjuk 180 fokkal", "isCorrect": false}, {"id": "a506b4e6-cbf4-4396-a654-aa8fd444a103", "text": "A pontot lefelé mozgatjuk 5 cm-rel", "isCorrect": false}], "timeLimit": 15}, {"id": "39e7eb21-ce8c-457e-856c-5e6f4cc6c502", "text": "Hol van a tengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "4d542601-2825-42d5-8095-c6c57f73d95b", "text": "Önmagában (fixpont)", "isCorrect": true}, {"id": "713a37f5-6e7e-4acb-97ea-9d8a77ccce9e", "text": "Az origóban", "isCorrect": false}, {"id": "c5955f2e-c80c-4026-a011-c10a184c0b07", "text": "Végtelenben", "isCorrect": false}, {"id": "09d20778-29e1-4e32-99e5-5ebe75f67359", "text": "A tengely másik végén", "isCorrect": false}], "timeLimit": 15}, {"id": "b2990c08-8096-4de4-835d-e44cc41eb45a", "text": "Ha a P pont 4 cm-re van a tükörtengelytől, milyen messze van a P'' tükörkép a tengelytől?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e4529bbe-0069-4cfb-a789-b6bc1a780f9b", "text": "Milyen messze van a P pont a P'' tükörképétől, ha a tengelytől való távolsága 4 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "b1fc81b0-6c35-4ca0-9466-2a371a4b165b", "text": "A tengelyes tükrözés egybevágósági transzformáció.", "type": "true-false", "options": [{"id": "2f826219-0461-45d8-8655-a7f9094c628f", "text": "Igaz", "isCorrect": true}, {"id": "5b0cdaf4-39ff-42a7-ac06-45b8608109c6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a46f2e7a-75bc-45c4-be6e-195df63a154f", "text": "A tengelyes tükrözés megváltoztatja az alakzat körüljárási irányát (pl. óramutató járásával megegyezőből ellentétes lesz).", "type": "true-false", "options": [{"id": "4fafd0bf-26d8-409c-8475-5993ef913aac", "text": "Igaz", "isCorrect": true}, {"id": "443a24be-027c-4760-b9c3-6401feb9e2cb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "13615267-46ad-41f4-93f5-5511032a14bb", "text": "A tengelyesen tükrös alakzat és tükörképe egybevágó.", "type": "true-false", "options": [{"id": "79135b25-45b1-40be-80d1-c7e88cd3cfda", "text": "Igaz", "isCorrect": true}, {"id": "4fa1f999-7355-4ce0-9204-1e6f4701ac78", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('17ac2c1d-897f-47a8-a7b9-e2b5be8828de', '21feff02-016d-46e2-bb9d-c27495133b1b', '58. óra: A tengelyes tükrözés tulajdonságai', 'Távolságtartás, szögtartás, körüljárási irány megváltozása, egyenes és kör tükörképe.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "e5123dc6-4d3c-4290-a1c7-2eb9a4bfac4d", "text": "Melyik tulajdonság érvényes a tengelyes tükrözésre?", "type": "multiple-choice", "options": [{"id": "c4e427e2-4bd4-4d0b-ae13-8219d6f3ca20", "text": "Távolságtartó, szögtartó, egyenestartó és megváltoztatja a körüljárási irányt", "isCorrect": true}, {"id": "b8b40ac2-f1bf-41a6-b76c-74c3418a06ab", "text": "Növeli a szakaszok hosszát", "isCorrect": false}, {"id": "d21e5853-0c6d-4bed-8e8d-da92b57d8ecb", "text": "Megváltoztatja a szögek nagyságát", "isCorrect": false}, {"id": "63e8a52c-de68-49f9-ba6a-65b162fb696f", "text": "Négyszögből háromszöget csinál", "isCorrect": false}], "timeLimit": 15}, {"id": "be8a13b5-127b-45ff-89a2-ace9b6fb422f", "text": "Egy 5 cm-es szakasz tengelyes tükörképe is 5 cm hosszú.", "type": "true-false", "options": [{"id": "c6e736a7-60cf-44be-8fee-bad08106844a", "text": "Igaz (távolságtartó)", "isCorrect": true}, {"id": "55de8d23-9b73-43dc-8871-46abf6c0c41d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "368a3642-e6e8-489c-be5b-d466e26818bb", "text": "Egy 45°-os szög tengelyes tükörképe is 45°-os.", "type": "true-false", "options": [{"id": "84d9a3ec-413b-4b2d-a5e6-3a620bd02cd5", "text": "Igaz (szögtartó)", "isCorrect": true}, {"id": "5aeb2512-09a0-4790-8c7e-c4c5c8d3df92", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b254037c-2d22-41be-af86-e4ecc28acf06", "text": "A tengelyre merőleges egyenes tükörképe önmaga (önmagába transzformálódik).", "type": "true-false", "options": [{"id": "ab3b53e4-e8f0-40ac-b3c1-30e7304a0131", "text": "Igaz", "isCorrect": true}, {"id": "45a61ffe-96d9-4d80-bcfa-a8b8e5e77fad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "079b3abb-e754-4cd4-bc6b-2fdb08b566ab", "text": "Egy kör tengelyes tükörképe ugyanolyan sugarú kör.", "type": "true-false", "options": [{"id": "b1fb5db9-b722-4de0-ad68-c97fda59dbd4", "text": "Igaz", "isCorrect": true}, {"id": "2359f3c4-7c0c-4dc1-953a-0a6ad53aa8e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "25eba905-8f4d-4d98-8330-64c38a740897", "text": "A tengellyel párhuzamos egyenes tükörképe is párhuzamos a tengellyel.", "type": "true-false", "options": [{"id": "0f91abfd-41b6-4818-9337-fa869ee1fe2b", "text": "Igaz", "isCorrect": true}, {"id": "65b85e20-2fda-46aa-8ca4-840e996ecd1e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1d191d6a-43dc-4d4a-81a7-3ad17a3e697d", "text": "Hány fixpontja (helyben maradó pontja) van a tengelyes tükrözésnek a síkban?", "type": "multiple-choice", "options": [{"id": "a246dec2-917d-4823-a657-c7ff01cd2d09", "text": "Végtelen sok (a tükörtengely minden pontja)", "isCorrect": true}, {"id": "3eb74e8d-835c-4336-90d3-6e88d4eff9f0", "text": "Csak 1", "isCorrect": false}, {"id": "37ace9ce-8555-4c24-88ef-9e17d38cb36d", "text": "Nincs egy sem", "isCorrect": false}, {"id": "91943744-6300-4552-853c-4475cf32b5e8", "text": "Pontosan 2", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('5b2e586d-f9fc-433d-9c3f-2c6fffefd681', '21feff02-016d-46e2-bb9d-c27495133b1b', '59. óra: Gyakorlóóra', 'Tengelyes tükörkép szerkesztésének gyakorlása pontok, szakaszok, sokszögek esetén.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "ae8de10d-1b4c-4778-82c6-37186b3e3ebd", "text": "Hogyan szerkesztjük meg egy P pont ''t'' tengelyre vonatkozó tükörképét?", "type": "multiple-choice", "options": [{"id": "1e940c66-d467-4874-bcd6-885ef470731c", "text": "Merőlegest állítunk P-ből ''t''-re, és a talpponttól felmérjük a P távolságát a merőlegesre", "isCorrect": true}, {"id": "6d847221-e757-4745-beab-ca5bb7cbbc7c", "text": "Párhuzamost húzunk ''t''-vel", "isCorrect": false}, {"id": "6b682c6e-feae-4084-9b93-f73a78f14268", "text": "Körzővel kört rajzolunk P középponttal", "isCorrect": false}, {"id": "bd10722a-0bc1-4da4-988e-4b8ac0d8ecbc", "text": "Összekötjük P-t az origóval", "isCorrect": false}], "timeLimit": 15}, {"id": "5c4c3db3-c0df-4d59-96cf-0f71bd6698e0", "text": "Egy háromszög tengelyes tükrözése után a kapott háromszög területe megegyezik az eredetivel.", "type": "true-false", "options": [{"id": "fb59952d-436b-4f40-a99a-90efc26184d7", "text": "Igaz", "isCorrect": true}, {"id": "35a692a5-4406-4138-be54-8faa2e09e36d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "787e09f7-16cc-456f-96f1-192ec5d8e004", "text": "Ha a P pont a tengelyen van, hol van a tükörképe?", "type": "multiple-choice", "options": [{"id": "e6651121-77aa-4402-821d-08bba1d593ab", "text": "Önmagában (P = P'')", "isCorrect": true}, {"id": "86c7f122-2985-4091-a5c7-16581a53c167", "text": "A tengely másik oldalán", "isCorrect": false}, {"id": "ad506607-881c-4963-a089-0fa475f3e3a4", "text": "A sík szélén", "isCorrect": false}, {"id": "b36cb4ef-9ea6-4ae1-95b5-3e296600e2c4", "text": "Az origóban", "isCorrect": false}], "timeLimit": 15}, {"id": "e0018adb-483e-4510-aebb-f5fb8469f1e5", "text": "A szakasz felezőmerőlegese a szakaszt önmagára tükrözi vissza.", "type": "true-false", "options": [{"id": "52f71280-16a5-47a6-83d3-cbe7a19646b6", "text": "Igaz", "isCorrect": true}, {"id": "748da7c4-8275-4652-ab75-76fee6a5775b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e39144fe-453b-4bb2-b731-a4968fdd7596", "text": "Melyik betűnek VAN függőleges szimmetriatengelye? (pl. A, M, Y, W)", "type": "multiple-choice", "options": [{"id": "a7650a7b-1048-4d2e-8452-15c43311a040", "text": "A", "isCorrect": true}, {"id": "d4e437f3-aa20-48ba-a0cc-0503d221acfb", "text": "F", "isCorrect": false}, {"id": "312086a3-5a1f-48d0-ae8d-a791e8a1f04d", "text": "L", "isCorrect": false}, {"id": "f555e8f8-a298-43a6-9f0e-02aff0713082", "text": "R", "isCorrect": false}], "timeLimit": 15}, {"id": "31c301f3-8c83-4b48-83b2-63d90584931a", "text": "Melyik betűnek VAN vízszintes szimmetriatengelye? (pl. B, C, D, E, K)", "type": "multiple-choice", "options": [{"id": "aaf54d9b-6f39-42e0-98aa-b5b4633cc0db", "text": "E", "isCorrect": true}, {"id": "d3aca8b2-62d7-4e62-bbe2-b2a43590a795", "text": "F", "isCorrect": false}, {"id": "028fcb4e-b86e-4182-a5bb-e8faa7e6db1d", "text": "G", "isCorrect": false}, {"id": "48ac3eff-a23e-4733-b837-9f079540dd88", "text": "J", "isCorrect": false}], "timeLimit": 15}, {"id": "f6763a91-4386-4572-8816-8d4b9485e8ad", "text": "A tengelyesen tükrös alakzatok szimmetrikusak a tükörtengelyre.", "type": "true-false", "options": [{"id": "34e94178-581b-4bc6-9ac0-257a0326f8dd", "text": "Igaz", "isCorrect": true}, {"id": "d586e50a-389e-47b9-bf06-4ce56a26fd53", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('fa403b58-0951-496a-a34b-e0dc911c5825', '21feff02-016d-46e2-bb9d-c27495133b1b', '60. óra: Tengelyes szimmetria', 'Tengelyesen szimmetrikus alakzatok, szögfelező és felezőmerőleges szimmetriatengelyként.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "60e7db01-9bc6-4d79-ba4d-fd1377da30d2", "text": "Mikor nevezünk egy síkidomot tengelyesen szimmetrikusnak?", "type": "multiple-choice", "options": [{"id": "fdf6c9de-bffa-4ba5-9249-3e38818e2dd0", "text": "Ha van legalább egy olyan egyenes (szimmetriatengely), amelyre tükrözve a síkidom önmagába megy át", "isCorrect": true}, {"id": "0c445090-c332-4ed1-aebe-145e9880e5b0", "text": "Ha minden oldala egyenlő", "isCorrect": false}, {"id": "ae89a49f-8b6d-4290-a63c-bdd75eda80c8", "text": "Ha kerek", "isCorrect": false}, {"id": "8c7f0512-64c8-4670-8291-5e3f7dce5044", "text": "Ha nincs szöge", "isCorrect": false}], "timeLimit": 15}, {"id": "a9d0b30c-cee1-4b96-8bcd-1b7a677dbda5", "text": "Mi a szögfelező egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "7821819d-75d3-4552-b05e-fc817f8c9415", "text": "A szögtartományt két egyenlő szögre osztja, és pontjai egyenlő távolságra vannak a szög száraitól", "isCorrect": true}, {"id": "f483cf67-a81c-4eca-b106-d44d535407ec", "text": "A szög szárait meghosszabbítja", "isCorrect": false}, {"id": "a648d5c2-4034-410b-918c-c03aee5bdce7", "text": "Merőleges a szög száira", "isCorrect": false}, {"id": "2984e55c-b22d-4091-944d-c651288850f3", "text": "Párhuzamos a szög száival", "isCorrect": false}], "timeLimit": 15}, {"id": "f6a85c4a-33a8-41db-98d6-f4beeb32eb17", "text": "A szögfelező egyenes a szög szimmetriatengelye.", "type": "true-false", "options": [{"id": "010bd9db-031f-41a0-8f88-54dc80c35395", "text": "Igaz", "isCorrect": true}, {"id": "97d559a0-763d-4f01-a4e3-c323591a2dc7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1cd027a9-92b0-4e1c-bf09-b40c9dab16d2", "text": "Hány szimmetriatengelye van egy 60°-os szögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "4fdc005c-2d7c-45a3-874b-4734bd4429c4", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "8bd05589-e613-4ad0-816e-f2986117b891", "text": "Végtelen sok (minden középponton átmenő egyenes)", "isCorrect": true}, {"id": "b70724a7-c4f4-4322-b78c-4908490a077b", "text": "1", "isCorrect": false}, {"id": "e6b0a179-b515-4b90-878a-7ef7773948fe", "text": "2", "isCorrect": false}, {"id": "0c48bf42-495c-4a51-9173-55e9ae5da791", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "0c7766a5-3d4c-402b-bd72-3f457babde67", "text": "A szögfelező megszerkesztéséhez körzőíveket használunk a szög szárain.", "type": "true-false", "options": [{"id": "2ef7f13a-4663-4ee4-99e1-3c270a20ccdd", "text": "Igaz", "isCorrect": true}, {"id": "e3f1ffa9-6dee-4e24-a424-8525cd3b2a7d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "681ccaca-0f51-4585-a330-5fee2dd359a3", "text": "Hány fokos két 30°-os részre osztja a szögfelező a 60°-os szöget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;